import 'dart:io';

import 'package:barcode_widget/barcode_widget.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:image/image.dart' as img;
import 'package:max_tools/tools/apps/qr_tool.dart';
import 'package:zxing2/qrcode.dart';

/// Tests for QR decoding, using a QR generated by the same library.
void main() {
  late Directory folder;

  setUp(() async {
    folder = await Directory.systemTemp.createTemp('max_tools_qr_');
  });

  tearDown(() async {
    if (folder.existsSync()) await folder.delete(recursive: true);
  });

  String writeQr(String content) {
    final qr = Encoder.encode(content, ErrorCorrectionLevel.h);
    final matrix = qr.matrix!;
    const scale = 8;
    final image = img.Image(
      width: matrix.width * scale,
      height: matrix.height * scale,
    );
    img.fill(image, color: img.ColorRgb8(255, 255, 255));
    for (var x = 0; x < matrix.width; x++) {
      for (var y = 0; y < matrix.height; y++) {
        if (matrix.get(x, y) == 1) {
          img.fillRect(
            image,
            x1: x * scale,
            y1: y * scale,
            x2: x * scale + scale,
            y2: y * scale + scale,
            color: img.ColorRgb8(0, 0, 0),
          );
        }
      }
    }
    final path = '${folder.path}${Platform.pathSeparator}code.png';
    File(path).writeAsBytesSync(img.encodePng(image));
    return path;
  }

  test('reads a QR code back out of an image', () {
    final path = writeQr('https://cambric.example/max-tools');
    expect(decodeQrFromPath(path), 'https://cambric.example/max-tools');
  });

  test('an image without a QR code returns null, not a wrong answer', () {
    final image = img.Image(width: 80, height: 80);
    img.fill(image, color: img.ColorRgb8(255, 255, 255));
    final path = '${folder.path}${Platform.pathSeparator}blank.png';
    File(path).writeAsBytesSync(img.encodePng(image));
    expect(decodeQrFromPath(path), isNull);
  });

  test('a text file is refused as not an image', () {
    final path = '${folder.path}${Platform.pathSeparator}not-image.txt';
    File(path).writeAsStringSync('hello');
    expect(
      () => decodeQrFromPath(path),
      throwsA(isA<FormatException>()),
    );
  });

  testWidgets('the preview appears only when there is content', (tester) async {
    tester.view.physicalSize = const Size(800, 1600);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    await tester.pumpWidget(const MaterialApp(home: QrTool()));
    await tester.pump();
    expect(find.textContaining('preview appears here'), findsOneWidget);

    await tester.enterText(find.byType(TextField).first, 'hello');
    await tester.pumpAndSettle();
    expect(find.byType(BarcodeWidget), findsOneWidget);
  });

  testWidgets('decoding asks for an image first', (tester) async {
    tester.view.physicalSize = const Size(800, 1600);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    await tester.pumpWidget(const MaterialApp(home: QrTool()));
    await tester.pump();
    await tester.ensureVisible(find.text('Read the code'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Read the code'));
    await tester.pump();
    expect(find.textContaining('Choose an image containing'), findsOneWidget);
  });
}
